frappe.ui.form.on("Stock Entry", {
    async onload_post_render(frm) {

        // Hanya untuk Stock Entry baru
        if (!frm.is_new()) return;

        // Hanya Manufacture
        if (frm.doc.purpose !== "Manufacture") return;

        // Harus berasal dari Work Order
        if (!frm.doc.work_order) return;

        try {
            const wo = await frappe.db.get_doc(
                "Work Order",
                frm.doc.work_order
            );

            if (!wo.custom_good_qty_postpacking) return;

            frm.doc.items.forEach(row => {

                // Finished Good:
                // Source Warehouse kosong
                // Target Warehouse terisi
                const is_finished_good =
                    !row.s_warehouse &&
                    !!row.t_warehouse;

                if (is_finished_good) {
                    frappe.model.set_value(
                        row.doctype,
                        row.name,
                        "qty",
                        wo.custom_good_qty_postpacking
                    );
                }
            });

            frm.refresh_field("items");

        } catch (e) {
            console.error(e);
        }
    }
});
